                contestRandom.reseed(mix(jumpSeed^0x57494e44ULL));const double wind=qBound(-12.,MyRandom::normalDistributionRandom(p["wind.mean"].toDouble()+ (athleteIndex==config["focus"].toInt()?p["athlete.windBias"].toDouble():0.),p["wind.deviation"].toDouble()),12.);
                simulator.setWinds(QVector<Wind>(5,Wind(wind)));simulator.setJumper(athlete);contestRandom.reseed(mix(jumpSeed^0x4a554d50ULL));simulator.simulateJump();auto jump=simulator.getJumpData();jump.setCompetition(&info);if(trial.team)results.addJump(currentTeam,jump);else results.addJump(athlete,jump);
                status.setJumpStatus(jump.getDSQ()?StartListCompetitorStatus::Dsq:StartListCompetitorStatus::Finished);status.setQualifiedBy95HSRule(jump.getLanding().getType()==Landing::Fall && JumpSimulator::isJumperBeat95HSPercents(jump.getDistance(),hill.getHSPoint()) && rules->getHas95HSRule());
